export default function PaymentPage({ onSuccess }) {
  return (
    <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "5px" }}>
      <h3>Payment</h3>
      <p>Scan the QR code or use UPI to pay</p>
      <div style={{ margin: "20px 0" }}>
        <p><strong>UPI ID:</strong> 8310549462@ybl</p>
        <p><strong>Amount:</strong> ₹200</p>
      </div>
      <button 
        onClick={onSuccess}
        style={{ 
          padding: "12px 24px", 
          cursor: "pointer",
          backgroundColor: "#4CAF50",
          color: "white",
          border: "none",
          borderRadius: "4px",
          fontSize: "16px"
        }}
      >
        Payment Done
      </button>
    </div>
  );
}
